import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/18-Data_Architecture_Whitepaper.html","title":"数据架构白皮书","lang":"en-US","frontmatter":{},"filePathRelative":"18-Data_Architecture_Whitepaper.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`18-Data_Architecture_Whitepaper.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e('<h1 id="数据架构白皮书" tabindex="-1"><a class="header-anchor" href="#数据架构白皮书"><span>数据架构白皮书</span></a></h1><blockquote><p>目的：统一 Apollo MMO 的玩家数据、运营 BI、缓存策略、TLog 方案，解决现有文档中“Blob VS 拆表”冲突，为 DataProxy 和数据库设计提供权威参考。</p></blockquote><h2 id="_1-设计原则" tabindex="-1"><a class="header-anchor" href="#_1-设计原则"><span>1. 设计原则</span></a></h2><ol><li><strong>游戏性能优先</strong>：逻辑服以 Protobuf/对象序列化方式读写，减少 DB 往返。</li><li><strong>可查询性</strong>：运营和 BI 核心字段需列化，支持 SQL 查询/聚合。</li><li><strong>最终一致性</strong>：大部分数据异步落地，关键资产（充值、交易）支持同步保障。</li><li><strong>混合存储</strong>：主 DB（MySQL 8.0）+ Redis Cache + Kafka/ClickHouse TLog；必要时引入 Mongo/ES 处理特定需求。</li><li><strong>可扩展性</strong>：分库分表、水平扩容、在线迁移；统一 DataProxy 层屏蔽底层变化。</li></ol><h2 id="_2-数据分类与落地" tabindex="-1"><a class="header-anchor" href="#_2-数据分类与落地"><span>2. 数据分类与落地</span></a></h2><table><thead><tr><th>数据类型</th><th>特点</th><th>落地策略</th><th>示例</th></tr></thead><tbody><tr><td>玩家主数据</td><td>强一致、结构复杂</td><td>Hybrid Schema：核心列 + Blob (Proto)</td><td>等级、战力、属性、背包</td></tr><tr><td>运行时状态</td><td>高频变更、短生命周期</td><td>Redis / 内存，定期落库</td><td>在线状态、场景位置、队伍</td></tr><tr><td>经济/交易</td><td>强一致、审计敏感</td><td>MySQL 事务 + TLog 双写</td><td>交易、拍卖、充值记录</td></tr><tr><td>社交数据</td><td>中等一致性、关联查询多</td><td>MySQL 分表 + Redis 缓存</td><td>公会、好友、邮件</td></tr><tr><td>行为日志</td><td>追加写、分析为主</td><td>TLog -&gt; Kafka -&gt; ClickHouse</td><td>金币流水、关卡日志</td></tr><tr><td>配置/静态</td><td>只读/少更新</td><td>配置系统 + CDN/版本管理</td><td>Excel → Lua/JSON</td></tr></tbody></table><h2 id="_3-hybrid-schema-详解" tabindex="-1"><a class="header-anchor" href="#_3-hybrid-schema-详解"><span>3. Hybrid Schema 详解</span></a></h2><h3 id="_3-1-表结构-示例-t-character" tabindex="-1"><a class="header-anchor" href="#_3-1-表结构-示例-t-character"><span>3.1 表结构（示例 <code>t_character</code>）</span></a></h3><div class="language-sql line-numbers-mode" data-highlighter="prismjs" data-ext="sql"><pre><code class="language-sql"><span class="line"><span class="token keyword">CREATE</span> <span class="token keyword">TABLE</span> <span class="token identifier"><span class="token punctuation">`</span>t_character<span class="token punctuation">`</span></span> <span class="token punctuation">(</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>char_id<span class="token punctuation">`</span></span> <span class="token keyword">BIGINT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>account_id<span class="token punctuation">`</span></span> <span class="token keyword">BIGINT</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>name<span class="token punctuation">`</span></span> <span class="token keyword">VARCHAR</span><span class="token punctuation">(</span><span class="token number">64</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>level<span class="token punctuation">`</span></span> <span class="token keyword">INT</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>vip_level<span class="token punctuation">`</span></span> <span class="token keyword">INT</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>power<span class="token punctuation">`</span></span> <span class="token keyword">BIGINT</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>gold<span class="token punctuation">`</span></span> <span class="token keyword">BIGINT</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>diamond<span class="token punctuation">`</span></span> <span class="token keyword">BIGINT</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>map_id<span class="token punctuation">`</span></span> <span class="token keyword">INT</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>last_login<span class="token punctuation">`</span></span> <span class="token keyword">DATETIME</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>data_bin<span class="token punctuation">`</span></span> <span class="token keyword">MEDIUMBLOB</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token identifier"><span class="token punctuation">`</span>version<span class="token punctuation">`</span></span> <span class="token keyword">BIGINT</span> <span class="token keyword">DEFAULT</span> <span class="token number">0</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token keyword">PRIMARY</span> <span class="token keyword">KEY</span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>char_id<span class="token punctuation">`</span></span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token keyword">KEY</span> <span class="token identifier"><span class="token punctuation">`</span>idx_account<span class="token punctuation">`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>account_id<span class="token punctuation">`</span></span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>\n<span class="line">    <span class="token keyword">KEY</span> <span class="token identifier"><span class="token punctuation">`</span>idx_level_power<span class="token punctuation">`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">`</span>level<span class="token punctuation">`</span></span><span class="token punctuation">,</span> <span class="token identifier"><span class="token punctuation">`</span>power<span class="token punctuation">`</span></span><span class="token punctuation">)</span></span>\n<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-blob-内容" tabindex="-1"><a class="header-anchor" href="#_3-2-blob-内容"><span>3.2 Blob 内容</span></a></h3><ul><li>使用 Protobuf（<code>PlayerProfile</code>）序列化：包含属性 map、背包、任务、技能等稀疏数据。</li><li>Blob 更新采用新旧版本对比（乐观锁 <code>version</code> 字段）避免覆盖。</li><li>DataProxy 负责 Protobuf 序列化/反序列化，业务逻辑只操作内存对象。</li></ul><h3 id="_3-3-列化字段" tabindex="-1"><a class="header-anchor" href="#_3-3-列化字段"><span>3.3 列化字段</span></a></h3><ul><li>只为高频查询/筛选字段列化（等级、战力、经济、地图、时间戳等）。</li><li>更新流程：内存对象更新 → 标记脏字段 → DataProxy 在写 DB 时同步更新列值。</li></ul><h2 id="_4-dataproxy-层" tabindex="-1"><a class="header-anchor" href="#_4-dataproxy-层"><span>4. DataProxy 层</span></a></h2><h3 id="_4-1-职责" tabindex="-1"><a class="header-anchor" href="#_4-1-职责"><span>4.1 职责</span></a></h3><ul><li>对业务屏蔽数据库细节，提供 <code>LoadPlayer</code>, <code>SavePlayer</code>, <code>QueryPlayers</code>, <code>UpdateEconomy</code> 等 API。</li><li>维护 Redis + MySQL 一致性（Write-Through/Write-Behind 策略）。</li><li>管理分库分表路由（ShardingKey = char_id/account_id）。</li><li>异步写队列 + WAL（本地日志）保障断电恢复。</li></ul><h3 id="_4-2-写策略" tabindex="-1"><a class="header-anchor" href="#_4-2-写策略"><span>4.2 写策略</span></a></h3><table><thead><tr><th>场景</th><th>策略</th></tr></thead><tbody><tr><td>玩家主数据</td><td>Write-Behind（先写 Redis/内存，异步批量刷 MySQL），关键操作强制 flush</td></tr><tr><td>货币变化</td><td>双写：Redis 立即更新 + TLog 记录 + 异步落库；关键交易同步写 DB</td></tr><tr><td>行为日志</td><td>仅写 TLog（Kafka）</td></tr><tr><td>公会/社交</td><td>视需求可使用 Write-Through（先写 DB，再更新缓存）</td></tr></tbody></table><h3 id="_4-3-缓存策略" tabindex="-1"><a class="header-anchor" href="#_4-3-缓存策略"><span>4.3 缓存策略</span></a></h3><ul><li>Redis Cluster：玩家快照、排行榜、限时活动状态；使用 Key 版本号 + TTL。</li><li>分布式锁/去重：使用 <code>SETNX</code> 或 RedLock 管理账号登录/操作。</li><li>缓存更新：通用模式（invalidate + reload），或通过订阅消息（Pub/Sub）同步。</li></ul><h2 id="_5-分库分表与扩容" tabindex="-1"><a class="header-anchor" href="#_5-分库分表与扩容"><span>5. 分库分表与扩容</span></a></h2><h3 id="_5-1-分片规则" tabindex="-1"><a class="header-anchor" href="#_5-1-分片规则"><span>5.1 分片规则</span></a></h3><ul><li>初期：账户维度（<code>char_id % N</code>）分片；<code>N</code> 根据容量预估。</li><li>采用 ShardingSphere 或自研路由：DataProxy 维护配置，动态刷新。</li><li>支持水平扩容：新增分片后，通过后台工具迁移数据（online re-sharding）。</li></ul><h3 id="_5-2-索引与归档" tabindex="-1"><a class="header-anchor" href="#_5-2-索引与归档"><span>5.2 索引与归档</span></a></h3><p>-冷数据（离线玩家、历史活动）定期归档至冷库（另一套 MySQL/ClickHouse）。</p><ul><li>归档策略：依据 <code>last_login</code>、<code>server merge</code> 产出的玩家列表。</li></ul><h2 id="_6-tlog-bi-流水" tabindex="-1"><a class="header-anchor" href="#_6-tlog-bi-流水"><span>6. TLog / BI 流水</span></a></h2><h3 id="_6-1-流程" tabindex="-1"><a class="header-anchor" href="#_6-1-流程"><span>6.1 流程</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">GameServer → LogAgent → Kafka → (实时) Flink → (离线) ClickHouse/Hive</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>LogAgent 采用 TCP/NNG，保障写入成功（异步 + 重试）。</li><li>Kafka Topic 按类型划分：MoneyFlow、ItemFlow、LevelFlow、QuestFlow 等。</li><li>ClickHouse 表支持近实时查询，提供 GM/BI 报表。</li></ul><h3 id="_6-2-日志规范" tabindex="-1"><a class="header-anchor" href="#_6-2-日志规范"><span>6.2 日志规范</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">timestamp | platform | server | player_id | event | delta | balance | reason | extra_json</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>事件枚举与 Protobuf 定义同步；DataProxy 可在写数据时触发 TLog。</li></ul><h2 id="_7-数据恢复与一致性" tabindex="-1"><a class="header-anchor" href="#_7-数据恢复与一致性"><span>7. 数据恢复与一致性</span></a></h2><ul><li><strong>WAL/备份</strong>：所有异步写操作在本地 WAL 记录，崩溃后重放；DB 定期全量 + 增量备份。</li><li><strong>热备</strong>：MySQL 主从复制 + MGR；Redis Cluster 多副本。</li><li><strong>一致性保障</strong>：关键资产操作使用事务或“请求落地后再响应”的策略；普通属性采用最终一致。</li><li><strong>容灾演练</strong>：定期演练 DB 故障、缓存丢失、Kafka 延迟等场景。</li></ul><h2 id="_8-工具与流程" tabindex="-1"><a class="header-anchor" href="#_8-工具与流程"><span>8. 工具与流程</span></a></h2><ul><li><strong>Schema 管理</strong>：使用 Flyway/Liquibase 或自研工具维护 SQL 版本。</li><li><strong>数据校验</strong>：定期比对 Redis vs MySQL，检查脏数据。</li><li><strong>数据导出</strong>：提供玩家数据导出/导入工具（GM 调试、问题排查）。</li><li><strong>监控</strong>：MySQL QPS/延迟、Redis 命中率、DataProxy 队列长度、Kafka backlog。</li></ul><h2 id="_9-统一决策" tabindex="-1"><a class="header-anchor" href="#_9-统一决策"><span>9. 统一决策</span></a></h2><ul><li>官方方案：采用 Hybrid Schema + DataProxy + TLog 系统。<code>docs/07</code> 与 <code>docs/08</code> 的差异以本白皮书为准。</li><li>Blob 仅对游戏逻辑敏感数据使用；BI/运营关注的字段必须列化。</li><li>DataProxy 是唯一入口，所有服务通过它访问持久层；不能直接绕过写 DB。</li></ul><h2 id="_10-roadmap" tabindex="-1"><a class="header-anchor" href="#_10-roadmap"><span>10. Roadmap</span></a></h2><ol><li>确定 <code>PlayerProfile</code> Protobuf 与列化字段列表，生成 C++/Lua/DB schema。</li><li>实现 DataProxy v1（Load/Save + Redis 缓存 + 写队列）。</li><li>搭建 Kafka/ClickHouse TLog 流水，定义日志枚举。</li><li>完成分库分表规划、迁移工具、备份策略。</li><li>接入监控/告警，制定操作流程（数据修复、回档）。</li></ol><hr><p>该白皮书为后续 DataProxy、DB 设计、BI 接入提供统一标准。***</p>',43)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};